import{c as s,Q as n,j as o,m as a}from"./chunks/framework.ByJJFMw8.js";const q=JSON.parse('{"title":"提示词工程基础（知识点笔记）","description":"","frontmatter":{},"headers":[],"relativePath":"posts/llm/提示词工程基础知识点笔记.md","filePath":"posts/llm/提示词工程基础知识点笔记.md","lastUpdated":null}'),r={name:"posts/llm/提示词工程基础知识点笔记.md"};function e(l,t,d,p,i,u){return n(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="提示词工程基础-知识点笔记" tabindex="-1">提示词工程基础（知识点笔记） <a class="header-anchor" href="#提示词工程基础-知识点笔记" aria-label="Permalink to &quot;提示词工程基础（知识点笔记）&quot;">​</a></h1><blockquote><p>来源：<a href="https://didilili.github.io/ai-agents-from-zero/#/1-2-%E6%8F%90%E7%A4%BA%E8%AF%8D%E5%B7%A5%E7%A8%8B%E5%9F%BA%E7%A1%80" target="_blank" rel="noreferrer">ai-agents-from-zero 第 1-2 章《提示词工程基础》</a>（<a href="https://github.com/didilili/ai-agents-from-zero" target="_blank" rel="noreferrer">GitHub 仓库</a>），原文配图与完整实操案例见原站。整理于 2026-11-26。</p></blockquote><p>本篇是五大工程模块的第一层（成本最低、见效最快），本文提炼其中最值得记住的知识点：提示词是什么、六要素怎么写、Zero/Few-shot 怎么选、System/User/Assistant 怎么拆、以及 Prompt 什么时候不够用。</p><h2 id="一、什么是提示词与提示词工程" tabindex="-1">一、什么是提示词与提示词工程 <a class="header-anchor" href="#一、什么是提示词与提示词工程" aria-label="Permalink to &quot;一、什么是提示词与提示词工程&quot;">​</a></h2><ul><li><strong>提示词（Prompt）</strong>：发给模型的输入内容，可以是一句话，也可以是一整套结构化消息。工程视角下，Prompt 不只是&quot;一句话问问题&quot;，而是<strong>把角色、任务、上下文、输入和输出规则组织清楚</strong>。</li><li><strong>为什么需要提示词</strong>：模型读过海量语料，但不会主动知道&quot;你这次想让它做什么&quot;。提示词的作用是告诉模型：扮演什么角色、任务是什么、可以参考什么资料、输出成什么样子。 <blockquote><p>提示词不是在&quot;教模型重新学知识&quot;，而是在<strong>激活它当前最该用的那部分能力</strong>。</p></blockquote></li><li><strong>为什么需要优化</strong>：高质量 Prompt 不是把模型&quot;变聪明&quot;，而是减少歧义、减少跑偏、减少格式错误。类比看医生：只说&quot;我不舒服&quot;没法判断，说清症状、持续时间、触发条件判断才准。<strong>输入越模糊，输出越容易漂</strong>。</li><li><strong>提示词工程（Prompt Engineering）</strong>：系统地设计、组织、测试和优化 Prompt，让模型在特定任务、约束和上下文下尽可能<strong>稳定</strong>地产出符合目标的结果。它不是玄学，有效与否看五件事：需求表达是否清晰、输入边界是否明确、输出结构是否可验收、示例是否足够说明边界、约束是否自洽。</li></ul><h2 id="二、上下文与上下文窗口" tabindex="-1">二、上下文与上下文窗口 <a class="header-anchor" href="#二、上下文与上下文窗口" aria-label="Permalink to &quot;二、上下文与上下文窗口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>含义</th><th>由此推出的工程结论</th></tr></thead><tbody><tr><td>上下文（Context）</td><td><strong>这一次</strong>实际喂给模型的全部输入：System 提示词 + 用户问题 + 历史对话 + 检索结果 + 工具返回</td><td>学 Prompt、RAG、工具调用，本质上都在学&quot;如何组织上下文&quot;</td></tr><tr><td>上下文窗口</td><td>模型一次最多能处理多长的上限（由架构和训练决定），超出会被截断、压缩或放不进</td><td>长文档不能无脑全塞；多轮对话要做摘要或裁剪；资料太多时往往要用 RAG</td></tr></tbody></table><h2 id="三、重心的变化-从-炫技巧-到-可检查的任务设计" tabindex="-1">三、重心的变化：从&quot;炫技巧&quot;到&quot;可检查的任务设计&quot; <a class="header-anchor" href="#三、重心的变化-从-炫技巧-到-可检查的任务设计" aria-label="Permalink to &quot;三、重心的变化：从&quot;炫技巧&quot;到&quot;可检查的任务设计&quot;&quot;">​</a></h2><ul><li>早期模型能力弱，开发者依赖&quot;技巧型 Prompt&quot;：复杂提示链、花式引导语、大量显式推理提示。</li><li>模型变强后，重点转向**&quot;把需求说清楚，并让结果可检查&quot;**。要问的不再是&quot;要不要加某个神秘句式&quot;，而是：任务定义清楚了吗？输入边界明确吗？输出格式可验收吗？背景和示例给够了吗？</li><li>技巧（Few-shot、分隔符、结构化输出、逐步拆解）仍有价值，但作用是让任务更清楚、更稳定、更容易验证，而不是靠某句神秘话术让模型突然变强。</li><li>工程系统需要的不是&quot;偶尔答对一次&quot;，而是<strong>能长期稳定复现，并可通过样例集或评测标准判断好坏</strong>。 <blockquote><p>提示词不是咒语，关键是把需求写到模型能执行。</p></blockquote></li></ul><h2 id="四、核心六要素-一段可执行提示词的构成" tabindex="-1">四、核心六要素：一段可执行提示词的构成 <a class="header-anchor" href="#四、核心六要素-一段可执行提示词的构成" aria-label="Permalink to &quot;四、核心六要素：一段可执行提示词的构成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要素</th><th>回答的问题</th><th>关键写法</th></tr></thead><tbody><tr><td><strong>角色</strong></td><td>你现在是谁</td><td>不是贴花哨身份，而是控制口吻语气、专业深度、思考视角、任务边界</td></tr><tr><td><strong>任务</strong></td><td>你要做什么</td><td><strong>指令动词开头</strong>（分析/总结/提取/分类/翻译/生成/重写/排序）+ 明确、具体、无歧义</td></tr><tr><td><strong>背景/上下文</strong></td><td>还需要知道什么</td><td>涉及特定读者、业务背景、历史记录、参考资料时很重要；不是堆资料，而是给更准确的理解起点</td></tr><tr><td><strong>输入数据</strong></td><td>本次处理哪段内容</td><td>用<strong>分隔符</strong>把指令、背景和原文隔开</td></tr><tr><td><strong>输出格式</strong></td><td>结果长什么样</td><td>JSON（程序处理）、Markdown（文档报告）、表格（分析对比）、代码；结果还要交给程序/工作流/解析器时<strong>必须先说清楚</strong></td></tr><tr><td><strong>质量与约束</strong></td><td>怎样算好、哪些事不能做</td><td>质量标准（文风、语气、粒度、专业程度）+ 约束条件（字数、来源限制、禁止编造、合规边界）</td></tr></tbody></table><ul><li>六要素不必每次写满，但它们是系统性检查 Prompt 是否完整的清单；任务越具体，模型越容易稳定命中目标。反例→正例：&quot;给我一个英语的学习计划&quot; → &quot;你扮演一名优秀的小学英语讲师，我是一名 3 年级学生，给我一个为期 3 个月提高英语成绩的学习计划&quot;。</li></ul><p>通用模板（最核心的可复用骨架）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 角色</span></span>
<span class="line"><span>你是一名【角色定位】。</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 任务</span></span>
<span class="line"><span>你的任务是基于给定的输入数据进行【分析 / 总结 / 对比 / 评估】。</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 背景/上下文</span></span>
<span class="line"><span>【历史记录总结】。【参考资料】。</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 输入数据</span></span>
<span class="line"><span>&lt;&lt;&lt;</span></span>
<span class="line"><span>{在此粘贴输入数据}</span></span>
<span class="line"><span>&gt;&gt;&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 输出格式</span></span>
<span class="line"><span>- 使用表格形式输出，必须包含：关键发现 / 支撑数据 / 结论 / 建议</span></span>
<span class="line"><span>- 表格下方给出整体结论说明</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 质量与约束</span></span>
<span class="line"><span>- 仅基于输入数据进行分析</span></span>
<span class="line"><span>- 不得编造、推测或引入外部信息</span></span>
<span class="line"><span>- 若输入数据不足以支撑结论，必须明确标注为&quot;信息不足&quot;</span></span>
<span class="line"><span>- 不允许为了完整性而补充假设</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><ul><li>原文用&quot;商品视频脚本生成&quot;完整实操演示六要素协同：角色控制专业视角、任务控制目标、输入数据承载产品信息、输出格式规定结构、约束控制质量与边界——这类 Prompt 很像真实项目里的系统提示词雏形。</li></ul><h2 id="五、分隔符-把-指令-和-输入-分开" tabindex="-1">五、分隔符：把&quot;指令&quot;和&quot;输入&quot;分开 <a class="header-anchor" href="#五、分隔符-把-指令-和-输入-分开" aria-label="Permalink to &quot;五、分隔符：把&quot;指令&quot;和&quot;输入&quot;分开&quot;">​</a></h2><ul><li>常见分隔符：三个反引号、三个双引号（<code>&quot;&quot;&quot;</code>）、<code>&lt;&lt;&lt; &gt;&gt;&gt;</code>、<code>&lt;&gt;</code>、<code>&lt;tag&gt;&lt;/tag&gt;</code>——用哪种不绝对，关键是<strong>一致且明确</strong>。</li><li>原文经典案例：直接说&quot;将下面的这句话翻译成英文。尽量使用华丽的词语&quot;，模型把&quot;尽量使用华丽的词语&quot;当成了待翻译文本；改成&quot;把用三个引号括起来的文本翻译成英文&quot;并用引号包住原文后，输出才正确。 <blockquote><p><strong>如果不把&quot;任务说明&quot;和&quot;原始输入&quot;分开，模型就可能把输入文本本身当成新的任务去执行。</strong></p></blockquote></li></ul><h2 id="六、zero-shot-与-few-shot" tabindex="-1">六、Zero-shot 与 Few-shot <a class="header-anchor" href="#六、zero-shot-与-few-shot" aria-label="Permalink to &quot;六、Zero-shot 与 Few-shot&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>做法</th><th>适用场景</th><th>特点</th></tr></thead><tbody><tr><td>Zero-shot</td><td>不给任何示例，直接让模型做任务</td><td>任务常见、目标边界清楚、模型已具备相关能力</td><td>简单、快、成本低；任务边界模糊时稳定性不如 Few-shot</td></tr><tr><td>Few-shot</td><td>先给几个示例，再让它按示例完成新任务</td><td>分类、抽取、改写、风格模仿、结构化输出——&quot;光靠解释还不够，最好直接告诉模型什么算对&quot;</td><td>示例直接把目标风格演示给模型看</td></tr></tbody></table><ul><li>Few-shot 常见格式：多组 <code>Q: &lt;问题&gt;</code> / <code>A: &lt;答案&gt;</code>，最后留 <code>Q: &lt;新问题&gt;? A:</code> 让模型续写。</li><li>原文经典案例：直接问&quot;圣诞老人会给我带礼物吗&quot;，模型回答&quot;虚构角色&quot;拆台；先给一组&quot;牙仙是真的吗？答：当然！……&quot;的示例演示&quot;配合想象&quot;的风格，模型就跟着示例风格走。 <blockquote><p><strong>示例不是&quot;再解释一遍任务&quot;，而是直接把目标风格演示给模型看。</strong></p></blockquote></li><li>示例怎么选才不带偏：覆盖真实边界（常见输入、边界输入、容易误判的输入 + 对应正确输出）；示例格式要和最终期望<strong>完全一致</strong>，否则模型会学到错误模式。</li></ul><h2 id="七、结构化组织-system-user-assistant" tabindex="-1">七、结构化组织：System / User / Assistant <a class="header-anchor" href="#七、结构化组织-system-user-assistant" aria-label="Permalink to &quot;七、结构化组织：System / User / Assistant&quot;">​</a></h2><p>为什么要结构化（三个原因）：<strong>模型没有真正的持久记忆</strong>（想保留上下文，历史内容仍要重新送进去）；<strong>固定内容和变化内容应该分开</strong>（每次整段重写既浪费 token 也不利维护）；<strong>项目开发需要可复用</strong>（系统角色、全局规则、用户输入、历史对话、工具结果来自不同模块）。</p><blockquote><p><strong>结构化 Prompt = 把不变的规则和会变化的输入拆开组织。</strong></p></blockquote><table tabindex="0"><thead><tr><th>消息类型</th><th>职责</th><th>放什么</th></tr></thead><tbody><tr><td>System</td><td>全局身份、规则、风格和长期约束</td><td>角色、长期任务边界、稳定背景、输出格式、质量与约束（稳定规则）</td></tr><tr><td>User</td><td>当前任务输入</td><td>本轮用户问题、输入数据、临时补充资料、外部资料/工具结果（动态输入）</td></tr><tr><td>Assistant</td><td>承接历史回复</td><td>历史回答、需要被后续轮次继续参考的中间结果</td></tr></tbody></table><p>六要素、模板、消息结构是<strong>同一件事的三个层次</strong>：</p><table tabindex="0"><thead><tr><th>层次</th><th>解决的问题</th></tr></thead><tbody><tr><td>提示词六要素</td><td>该告诉模型哪些信息（写什么）</td></tr><tr><td>提示词模板</td><td>如何组织成可复用结构（哪些固定、哪些运行时替换）</td></tr><tr><td>消息结构</td><td>运行时放到哪类消息里（怎么装配）</td></tr></tbody></table><blockquote><p><strong>六要素回答&quot;写什么&quot;，模板回答&quot;怎么复用&quot;，消息结构回答&quot;运行时怎么装配&quot;。</strong></p></blockquote><ul><li>落到后续章节：RAG 中动态上下文填充检索到的知识库片段；Agent 中工具返回、历史动作、观察结果不断追加进消息上下文；LangChain 中落到 <code>PromptTemplate</code>、<code>ChatPromptTemplate</code>、<code>MessagesPlaceholder</code> 等对象。</li><li>真实项目里的 Prompt 更像一套<strong>输入装配规则</strong>：哪些固定、哪些动态、哪些来自知识库、哪些来自工具，最后怎么一起送进模型。</li></ul><h2 id="八、提示词工程的边界-什么时候单靠-prompt-不够" tabindex="-1">八、提示词工程的边界：什么时候单靠 Prompt 不够 <a class="header-anchor" href="#八、提示词工程的边界-什么时候单靠-prompt-不够" aria-label="Permalink to &quot;八、提示词工程的边界：什么时候单靠 Prompt 不够&quot;">​</a></h2><p>问题本质不再是&quot;怎么问&quot;，而是模型缺知识、缺流程、缺行为稳定性时，需要其他模块配合：</p><table tabindex="0"><thead><tr><th>场景</th><th>问题本质</th><th>解决办法</th></tr></thead><tbody><tr><td>参考资料太多</td><td>资料接近/超过上下文窗口，&quot;资料太多，模型吃不下&quot;</td><td>资料筛选、摘要，或直接上 RAG</td></tr><tr><td>多步骤复杂流程</td><td>一次生成里容易跳步、漏步、顺序混乱</td><td>把大任务拆成多个小 Prompt，或用工作流组织</td></tr><tr><td>指令遵循能力不足</td><td>对格式、结构和复杂指令的遵循有天花板</td><td>关键要求前置；仍不稳则换模型、结构化输出方案，甚至微调</td></tr><tr><td>缺少领域知识</td><td>Prompt 再清楚也不能凭空补足知识</td><td>优先补上下文或知识库；再进一步才考虑微调/续训</td></tr></tbody></table><ul><li><strong>位置敏感性</strong>：研究表明许多模型对提示<strong>开头和结尾</strong>位置的信息更敏感，中间部分更容易&quot;丢失关注&quot;——<strong>不要把最重要的要求埋在中间</strong>。</li></ul><h2 id="九、常见误区与注意点" tabindex="-1">九、常见误区与注意点 <a class="header-anchor" href="#九、常见误区与注意点" aria-label="Permalink to &quot;九、常见误区与注意点&quot;">​</a></h2><ol><li><strong>不要把礼貌当成优化核心</strong>：&quot;请、谢谢&quot;通常不会显著提升效果。<strong>礼貌不是主要优化杠杆，清晰才是</strong>——影响结果的是任务是否清楚、边界是否明确、输出是否可验收。</li><li><strong>多个任务不要混在一起</strong>：一个 Prompt 同时塞&quot;先总结、再分类、再评价、再输出复杂 JSON&quot;等太多目标，模型容易顾此失彼，效果明显下降；复杂任务拆开或用工作流串起来。</li><li><strong>允许 LLM 说&quot;我不知道&quot;</strong>：总要求&quot;必须回答&quot;，模型更容易编。高风险、信息不足或需要事实依据的场景，应明确允许模型承认不确定性（如&quot;如果您对任何方面不确定……请说&#39;我没有足够的信息来自信地评估这一点&#39;&quot;）——这类约束<strong>对降低幻觉非常有帮助</strong>。</li><li><strong>指令自相矛盾</strong>：一边要求&quot;简洁&quot;一边要求&quot;详细全面&quot;，模型会陷入冲突（&quot;写一段简洁的详细介绍&quot;天然不自洽）；必须兼顾多个目标时明确优先级。</li><li><strong>不要迷信&quot;魔法词&quot;</strong>：<code>Let&#39;s think step by step</code>、<code>Take a deep breath and think this through</code> 等句式只在某些模型/任务/时期可能有帮助，绝不是稳定、通用、可迁移的万能钥匙。更可靠的做法：任务拆清楚、给足示例、明确输出格式、约束不确定时允许拒答。 <blockquote><p><strong>不要迷信一句&quot;咒语&quot;，要重视完整的任务设计。</strong></p></blockquote></li></ol><h2 id="十、prompt-调优的正确姿势-有证据地迭代" tabindex="-1">十、Prompt 调优的正确姿势：有证据地迭代 <a class="header-anchor" href="#十、prompt-调优的正确姿势-有证据地迭代" aria-label="Permalink to &quot;十、Prompt 调优的正确姿势：有证据地迭代&quot;">​</a></h2><ul><li><strong>过度优化陷阱</strong>：在词句上来回抠，收益微小；没有固定测试样例时，甚至不知道改动是真的变好了，还是&quot;刚好命中某一次输出&quot;。</li><li>更值得优先优化的通常是：结构是否清楚、任务是否明确、输入是否分隔、是否缺示例、输出格式是否合理——而不是纠结&quot;写请帮我还是请你帮我&quot;。</li><li><strong>样例集迭代法</strong>：对稍微重要的 Prompt 保留 <strong>5-10 个真实样例</strong>，每次改完用同一批样例重测，比较格式正确率、事实错误、遗漏字段和人工评分，让调优从&quot;凭感觉改词&quot;变成&quot;有证据地迭代&quot;。</li><li><strong>换模型要重新调优</strong>：不同模型的指令遵循习惯、输出倾向、工具调用风格、上下文利用能力都不一样，一个模型上表现不错的 Prompt，换模型后往往需要重新验证和调整。</li><li>Prompt 调优本质是<strong>实验性工作</strong>：有方法也有试错，但有效的试错是基于结构、目标和评测来迭代，而不是无意义地反复换词。</li></ul><h2 id="十一、一页速记" tabindex="-1">十一、一页速记 <a class="header-anchor" href="#十一、一页速记" aria-label="Permalink to &quot;十一、一页速记&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关键词</th><th>一句话</th></tr></thead><tbody><tr><td>提示词</td><td>发给模型的输入 = 角色、任务、上下文、输入、输出规则的组织</td></tr><tr><td>六要素</td><td>角色、任务、背景/上下文、输入数据、输出格式、质量与约束（完整性检查清单，不必写满）</td></tr><tr><td>Zero / Few-shot</td><td>不举例 vs 先示范；任务边界说不清就用 Few-shot，示例要覆盖边界且格式一致</td></tr><tr><td>结构化</td><td>System 放稳定规则，User 放动态输入，Assistant 承接历史结果</td></tr><tr><td>边界</td><td>资料多→RAG；流程复杂→拆步骤/工作流；指令遵循差→换模型/微调；缺知识→知识库/续训</td></tr><tr><td>误区</td><td>别指望礼貌和魔法词；任务别混；允许说&quot;不知道&quot;；用样例集有证据地迭代</td></tr></tbody></table>`,38)])])}const b=s(r,[["render",e]]);export{q as __pageData,b as default};
